const msg = $json.message || {};
const from = msg.from || {};
const text = String(msg.text || '').trim();

return [{
  json: {
    telegram_id: String(from.id || ''),
    chat_id: String(msg.chat?.id || from.id || ''),
    nombre: [from.first_name, from.last_name].filter(Boolean).join(' '),
    texto: text
  }
}];

const evt = $('Normalizar Evento').first().json;

const menu = $('Leer MENU').all().map(i=>i.json).filter(x=>x.id_producto);
const users = $('Leer USUARIOS').all().map(i=>i.json).filter(x=>x.telegram_id);
const sessions = $('Leer SESSIONS').all().map(i=>i.json).filter(x=>x.telegram_id);
const orders = $('Leer PEDIDOS').all().map(i=>i.json).filter(x=>x.id_pedido);

const existingUser = users.find(u=>String(u.telegram_id)===String(evt.telegram_id));
const existingSession = sessions.find(s=>String(s.telegram_id)===String(evt.telegram_id));

let cart=[];
try { cart=JSON.parse(existingSession?.carrito_temporal || '[]'); } catch { cart=[]; }

const money=n=>new Intl.NumberFormat('es-CO',{
  style:'currency',currency:'COP',maximumFractionDigits:0
}).format(Number(n||0));

const cartTotal=()=>cart.reduce(
  (sum,item)=>sum+Number(item.precio)*Number(item.cantidad),0
);

const menuText=()=>{
  const categories=['Bebidas','Comidas','Snacks'];
  let txt='📋 *MENÚ DELIVERYBOT*\n';
  for(const cat of categories){
    const items=menu.filter(p=>String(p.categoria)===cat && Number(p.stock)>0);
    if(!items.length) continue;
    txt+=`\n*${cat.toUpperCase()}*\n`;
    for(const p of items){
      txt+=`${p.id_producto} · ${p.nombre} · ${money(p.precio)} · Stock ${p.stock}\n`;
    }
  }
  txt+='\nPara agregar escribe:\n`AGREGAR BEB001 2`\n\nComandos: /carrito · /confirmar · /estado · /historial';
  return txt;
};

const raw=String(evt.texto||'').trim();
const upper=raw.toUpperCase();

let response={
  chat_id:evt.chat_id,
  text:'',
  order:null,
  stock_updates:[],
  state_update:null,
  kitchen_text:'',
  user_record:{
    telegram_id:evt.telegram_id,
    nombre_completo:evt.nombre || existingUser?.nombre_completo || 'Usuario Telegram',
    departamento_oficina:existingUser?.departamento_oficina || 'POR DEFINIR',
    puntos_lealtad:Number(existingUser?.puntos_lealtad || 0)
  },
  session_record:{
    telegram_id:evt.telegram_id,
    pantalla_actual:'COMANDOS',
    carrito_temporal:'[]',
    ultimo_cambio:new Date().toISOString()
  }
};

if(['/START','/MENU','MENU','HOLA','BUENAS','BUENOS DÍAS','BUENOS DIAS'].includes(upper)){
  response.text=`☕ *DeliveryBot Cafetería*\n\nHola ${evt.nombre||'👋'}.\nPuedes pedir usando comandos sencillos.\n\n${menuText()}`;

}else if(/^(?:AGREGAR\s+)?[A-Z]{3}\d{3}\s+\d+$/.test(upper)){
  const parts=upper.replace(/^AGREGAR\s+/,'').split(/\s+/);
  const id=parts[0];
  const qty=Number(parts[1]);
  const p=menu.find(x=>String(x.id_producto).toUpperCase()===id);

  if(!p){
    response.text=`❌ No encontré el producto ${id}. Envía /menu para ver los códigos.`;
  }else if(qty<1 || qty>10){
    response.text='⚠️ La cantidad debe estar entre 1 y 10.';
  }else{
    const inCart=cart.find(x=>x.id===id);
    const currentQty=Number(inCart?.cantidad||0);

    if(currentQty+qty>Number(p.stock)){
      response.text=`⚠️ Stock insuficiente de ${p.nombre}. Disponible: ${p.stock}.`;
    }else{
      if(inCart) inCart.cantidad=currentQty+qty;
      else cart.push({id,nombre:p.nombre,cantidad:qty,precio:Number(p.precio)});

      response.text=`✅ Agregado: ${qty} × *${p.nombre}*\nSubtotal: *${money(cartTotal())}*\n\nEnvía /carrito para revisar o /menu para seguir comprando.`;
    }
  }

}else if(upper==='/CARRITO' || upper==='CARRITO'){
  if(!cart.length){
    response.text='🛒 Tu carrito está vacío. Envía /menu para comenzar.';
  }else{
    const lines=cart.map(x=>`• ${x.cantidad} × ${x.nombre} = ${money(Number(x.cantidad)*Number(x.precio))}`).join('\n');
    response.text=`🛒 *TU CARRITO*\n\n${lines}\n\n*TOTAL: ${money(cartTotal())}*\n\nEnvía /confirmar para crear el pedido o /vaciar para empezar de nuevo.`;
  }

}else if(upper==='/VACIAR' || upper==='VACIAR'){
  cart=[];
  response.text='🗑️ Carrito vaciado. Envía /menu para hacer un nuevo pedido.';

}else if(upper==='/CONFIRMAR' || upper==='CONFIRMAR'){
  if(!cart.length){
    response.text='⚠️ No puedes confirmar porque el carrito está vacío.';
  }else{
    const faltantes=[];
    for(const x of cart){
      const p=menu.find(m=>String(m.id_producto)===String(x.id));
      if(!p || Number(p.stock)<Number(x.cantidad)) faltantes.push(x.nombre);
    }

    if(faltantes.length){
      response.text=`⚠️ El stock cambió para: ${faltantes.join(', ')}.\nEnvía /menu y ajusta el pedido.`;
    }else{
      const now=new Date();
      const date=now.toLocaleDateString('en-CA',{timeZone:'America/Bogota'});
      const time=now.toLocaleTimeString('es-CO',{
        timeZone:'America/Bogota',hour:'2-digit',minute:'2-digit',hour12:false
      });
      const idPedido=`DB-${date.replaceAll('-','')}-${String(now.getTime()).slice(-6)}`;
      const total=cartTotal();

      response.order={
        id_pedido:idPedido,
        id_usuario:evt.telegram_id,
        detalles_pedido:JSON.stringify(cart),
        total_pago:total,
        estado:'Recibido',
        fecha:date,
        hora:time
      };

      response.stock_updates=cart.map(x=>{
        const p=menu.find(m=>String(m.id_producto)===String(x.id));
        return {id_producto:x.id,stock:Number(p.stock)-Number(x.cantidad)};
      });

      const kitchenLines=cart.map(x=>`${x.cantidad} × ${x.nombre}`).join('\n');

      response.kitchen_text=`🔔 *NUEVO PEDIDO*\n\nPedido: *${idPedido}*\n${kitchenLines}\n\nTotal: *${money(total)}*\n\nPara actualizar estado:\nESTADO ${idPedido} PREPARACION`;

      response.text=`✅ *PEDIDO CONFIRMADO*\n\nNúmero: *${idPedido}*\nTotal: *${money(total)}*\nEstado: *Recibido*\n\nEnvía /estado para consultar el avance.`;

      response.user_record.puntos_lealtad=
        Number(response.user_record.puntos_lealtad)+Math.floor(total/1000);

      cart=[];
    }
  }

}else if(/^ESTADO\s+DB-\S+\s+.+$/i.test(raw)){
  const match=raw.match(/^ESTADO\s+(DB-\S+)\s+(.+)$/i);
  const idPedido=match[1];
  const requested=match[2]
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replaceAll('_',' ').trim().toUpperCase();

  const states={
    'RECIBIDO':'Recibido',
    'PREPARACION':'Preparación',
    'EN CAMINO':'En camino',
    'ENTREGADO':'Entregado',
    'CANCELADO':'Cancelado'
  };

  const newState=states[requested];
  const order=orders.find(o=>String(o.id_pedido)===idPedido);

  if(!order){
    response.text=`❌ No encontré el pedido ${idPedido}.`;
  }else if(!newState){
    response.text='⚠️ Estado inválido. Usa PREPARACION, EN_CAMINO, ENTREGADO o CANCELADO.';
  }else{
    response.state_update={
      id_pedido:idPedido,
      estado:newState,
      id_usuario:String(order.id_usuario),
      user_text:`📦 *Actualización de pedido*\n\nPedido: *${idPedido}*\nNuevo estado: *${newState}*`
    };
    response.text=`✅ ${idPedido} actualizado a *${newState}*.`;
  }

}else if(upper==='/ESTADO' || upper==='ESTADO'){
  const myOrders=orders.filter(o=>String(o.id_usuario)===String(evt.telegram_id));
  const last=myOrders.length ? myOrders[myOrders.length-1] : null;

  if(!last){
    response.text='📦 Todavía no tienes pedidos registrados.';
  }else{
    response.text=`📦 *ESTADO DE TU PEDIDO*\n\nPedido: *${last.id_pedido}*\nEstado: *${last.estado}*\nTotal: *${money(last.total_pago)}*\nFecha: ${last.fecha} ${last.hora}`;
  }

}else if(upper==='/HISTORIAL' || upper==='HISTORIAL'){
  const myOrders=orders
    .filter(o=>String(o.id_usuario)===String(evt.telegram_id))
    .slice(-5).reverse();

  if(!myOrders.length){
    response.text='📜 No tienes pedidos anteriores.';
  }else{
    response.text='📜 *ÚLTIMOS PEDIDOS*\n\n'+myOrders.map(
      o=>`• ${o.id_pedido} · ${o.estado} · ${money(o.total_pago)} · ${o.fecha}`
    ).join('\n');
  }

}else{
  response.text='No entendí el comando.\n\nUsa:\n/menu\nAGREGAR BEB001 2\n/carrito\n/confirmar\n/vaciar\n/estado\n/historial';
}

response.session_record.carrito_temporal=JSON.stringify(cart);
response.session_record.ultimo_cambio=new Date().toISOString();

return [{json:response}];
